151	/* =========================================================
152	 * 一、初始化 & 行情更新
153	 * ========================================================= */
154	
155	/** 初始化股市 */
156	function initStockMarket(state) {
157	  for (const stock of STOCK_LIST) {
158	    state.corporate.stockMarket[stock.symbol] = {
159	      price: stock.basePrice * (0.85 + Math.random() * 0.3),
160	      history: [], // [{ day, price }]
161	      high20: stock.basePrice,
162	      low20: stock.basePrice,
163	      lastNewsDay: -999,
164	      _initialized: false,
165	    };
166	  }
167	}
168	
169	/** 初始化时填入少量历史走势 */
170	function bootstrapStockHistory(state) {
171	  for (const sym of Object.keys(state.corporate.stockMarket)) {
172	    const market = state.corporate.stockMarket[sym];
173	    const def = STOCK_LIST.find((s) => s.symbol === sym);
174	    if (!def) continue;
175	    if (!market._initialized) {
176	      market._initialized = true;
177	      // 倒推 20 天历史
178	      let p = market.price / (0.85 + Math.random() * 0.3);
179	      for (let i = 0; i < 20; i++) {
180	        const change = 1 + (Math.random() - 0.5) * def.volatility;
181	        p = p * change;
182	        market.history.push({ day: state.player.day - (20 - i), price: p });
183	      }
184	      market.history.push({ day: state.player.day, price: market.price });
185	      market.high20 = Math.max(...market.history.map((h) => h.price));
186	      market.low20 = Math.min(...market.history.map((h) => h.price));
187	    }
188	  }
189	}
190	
191	/** 更新股市价格（每日 / 季末） */
192	function updateStockPrices(state, forceNews = false) {
193	  for (const stock of STOCK_LIST) {
194	    const market = state.corporate.stockMarket[stock.symbol];
195	    if (!market) continue;
196	
197	    // 1) 基础趋势（每日漂移）
198	    const trend = stock.baseTrend;
199	    // 2) 随机扰动（正态分布近似）
200	    const noise = (Math.random() - 0.5) * 2 * stock.volatility;
201	    // 3) 均值回归（偏离20日均价过远时拉回一些）
202	    let meanReversion = 0;
203	    if (market.history.length >= 5) {
204	      const recent = market.history.slice(-5);
205	      const avg = recent.reduce((s, h) => s + h.price, 0) / recent.length;
206	      meanReversion = ((avg - market.price) / avg) * 0.15;
207	    }
208	    const change = 1 + trend + noise + meanReversion;
209	    market.price = Math.max(0.5, market.price * change);
210	    market.price = Math.round(market.price * 100) / 100;
211	
212	    // 4) 新闻冲击（5% 概率触发）
213	    if (forceNews || Math.random() < 0.05) {
214	      const newsPool = STOCK_NEWS_TEMPLATES.find(
215	        (n) => n.symbol === stock.symbol,
216	      );
217	      if (newsPool && state.player.day - market.lastNewsDay > 3) {
218	        const news =
219	          newsPool.headlines[
220	            Math.floor(Math.random() * newsPool.headlines.length)
221	          ];
222	        market.price = Math.max(0.5, market.price * (1 + news.impact));
223	        market.price = Math.round(market.price * 100) / 100;
224	        market.lastNewsDay = state.player.day;
225	        StateManager.addMessage(
226	          `📊 [${stock.symbol}] ${news.text}`,
227	          news.impact > 0 ? "success" : "danger",
228	        );
229	      }
230	    }
231	
232	    // 记录历史
233	    market.history.push({ day: state.player.day, price: market.price });
234	    if (market.history.length > 20) market.history.shift();
235	    market.high20 = Math.max(...market.history.map((h) => h.price));
236	    market.low20 = Math.min(...market.history.map((h) => h.price));
237	  }
238	}
239	
240	/* =========================================================
241	 * 二、买卖接口
242	 * ========================================================= */
243	
244	/** 买入股票 */
245	function buyStock(symbol, shares) {
246	  const state = StateManager.getState();
247	  const market = state.corporate.stockMarket[symbol];
248	  if (!market) {
249	    StateManager.addMessage("⚠️ 不存在的股票。", "danger");
250	    return false;
251	  }
252	
253	  shares = Math.floor(shares);
254	  if (shares <= 0) {
255	    StateManager.addMessage("⚠️ 至少买入1股。", "warning");
256	    return false;
257	  }
258	
259	  const cost = Math.round(market.price * shares * 100) / 100;
260	  if (state.resources.cash < cost) {
261	    StateManager.addMessage(
262	      `⚠️ 需要 ¥${cost.toLocaleString()}，现金不足。`,
263	      "danger",
264	    );
265	    return false;
266	  }
267	
268	  state.resources.cash -= cost;
269	
270	  const existing = state.corporate.stocks.find((s) => s.symbol === symbol);
271	  if (existing) {
272	    const totalShares = existing.shares + shares;
273	    existing.avgPrice =
274	      Math.round(
275	        ((existing.avgPrice * existing.shares + cost) / totalShares) * 100,
276	      ) / 100;
277	    existing.shares = totalShares;
278	  } else {
279	    state.corporate.stocks.push({
280	      symbol,
281	      name: STOCK_LIST.find((s) => s.symbol === symbol)?.name || symbol,
282	      shares,
283	      avgPrice: market.price,
284	    });
285	  }
286	
287	  StateManager.addMessage(
288	    `📈 买入 ${symbol} ×${shares}股 @¥${market.price}，共 ¥${cost.toLocaleString()}`,
289	    "success",
290	  );
291	
292	  // Phase 2：记录交易日志（供内幕交易审查）
293	  if (typeof logTrade === "function") {
294	    var rumor = state.insiderTrading?.activeRumor;
295	    var relatedRumorId = null;
296	    if (rumor && !rumor.resolvedDay) {
297	      // 检查当前交易是否与风声公司相关
298	      if (CORP_STOCK_MAP) {
299	        for (var cid in CORP_STOCK_MAP) {
300	          if (
301	            CORP_STOCK_MAP[cid].indexOf(symbol) >= 0 &&
302	            cid === rumor.companyId
303	          ) {
304	            relatedRumorId = rumor.id;
305	            break;
306	          }
307	        }
308	      }
309	    }
310	    logTrade(state, symbol, "buy", shares, market.price, relatedRumorId);
311	  }
312	
313	  return true;
314	}
315	
316	/** 卖出股票 */
317	function sellStock(symbol, shares) {
318	  const state = StateManager.getState();
319	  const holding = state.corporate.stocks.find((s) => s.symbol === symbol);
320	  if (!holding || holding.shares < shares) {
321	    StateManager.addMessage("⚠️ 持仓不足。", "danger");
322	    return false;
323	  }
324	
325	  const market = state.corporate.stockMarket[symbol];
326	  const revenue = Math.round(market.price * shares * 100) / 100;
327	  const profit = revenue - holding.avgPrice * shares;
328	
329	  state.resources.cash += revenue;
330	  state.resources.totalEarned += Math.max(0, profit);
331	
332	  holding.shares -= shares;
333	  if (holding.shares <= 0) {
334	    state.corporate.stocks = state.corporate.stocks.filter(
335	      (s) => s.symbol !== symbol,
336	    );
337	  }
338	
339	  const profitStr =
340	    profit >= 0
341	      ? `📈 盈利 ¥${Math.round(profit).toLocaleString()}`
342	      : `📉 亏损 ¥${Math.abs(Math.round(profit)).toLocaleString()}`;
343	  StateManager.addMessage(
344	    `💰 卖出 ${symbol} ×${shares}股，¥${revenue.toLocaleString()}。${profitStr}`,
345	    profit >= 0 ? "success" : "warning",
346	  );
347	
348	  // Phase 2：记录交易日志（供内幕交易审查）
349	  if (typeof logTrade === "function") {
350	    var rumor = state.insiderTrading?.activeRumor;
351	    var relatedRumorId = null;
352	    if (rumor && !rumor.resolvedDay) {
353	      if (CORP_STOCK_MAP) {
354	        for (var cid in CORP_STOCK_MAP) {
355	          if (
356	            CORP_STOCK_MAP[cid].indexOf(symbol) >= 0 &&
357	            cid === rumor.companyId
358	          ) {
359	            relatedRumorId = rumor.id;
360	            break;
361	          }
362	        }
363	      }
364	    }
365	    logTrade(state, symbol, "sell", shares, market.price, relatedRumorId);
366	  }
367	
368	  return true;
369	}
370	
371	/** 计算能全部买入的股数（按当前价） */
372	function calcMaxBuyShares(symbol) {
373	  const state = StateManager.getState();
374	  const market = state.corporate.stockMarket[symbol];
375	  if (!market || market.price <= 0) return 0;
376	  // 保留 1 元，避免精度问题
377	  const cash = Math.max(0, state.resources.cash - 1);
378	  return Math.floor(cash / market.price);
379	}
380	
381	/* =========================================================
382	 * 三、交易 UI
383	 * ========================================================= */
384	
385	/** 渲染简易 K 线（折线图 + 颜色块） */
386	function renderKLine(history, currentPrice) {
387	  if (!history || history.length < 2) {
388	    return '<div style="color:var(--text-muted);font-size:10px;">无历史数据</div>';
389	  }
390	  const prices = history.map((h) => h.price);
391	  const max = Math.max(...prices, currentPrice);
392	  const min = Math.min(...prices, currentPrice);
393	  const range = max - min || 1;
394	  const w = 140; // svg width
395	  const h = 40; // svg height
396	  const stepX = w / (history.length - 1);
397	  const points = history
398	    .map((p, i) => {
399	      const x = i * stepX;
400	      const y = h - ((p.price - min) / range) * h;
401	      return `${x.toFixed(1)},${y.toFixed(1)}`;
402	    })
403	    .join(" ");
404	
405	  // 折线/填充使用固定色（信息蓝），不随涨跌方向变化
406	  // 方向信息由价格数字和涨跌幅文字（红涨绿跌）负责
407	  const lineColor = "var(--info)";
408	  const fillColor = "rgba(90,138,180,0.12)";
409	
410	  // 构造一个 polygon 用于填充
411	  const fillPoints = `0,${h} ${points} ${w},${h}`;
412	
413	  return `
414	    <svg width="${w}" height="${h}" style="display:block;margin-top:4px;">
415	      <polygon points="${fillPoints}" fill="${fillColor}" />
416	      <polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5" />
417	    </svg>
418	  `;
419	}
420	
421	/** 渲染单只股票卡片 */
422	function renderStockCard(stock, state) {
423	  const market = state.corporate.stockMarket[stock.symbol];
424	  if (!market) return "";
425	  const price = market.price;
426	  const holding = state.corporate.stocks.find((s) => s.symbol === stock.symbol);
427	  const shares = holding ? holding.shares : 0;
428	
429	  // 今日涨跌（vs 上一日）
430	  const prev =
431	    market.history.length >= 2
432	      ? market.history[market.history.length - 2].price
433	      : price;
434	  const todayChange = price - prev;
435	  const todayPct = (todayChange / prev) * 100;
436	
437	  // 7日均价
438	  const last7 = market.history.slice(-7);
439	  const avg7 =
440	    last7.length > 0
441	      ? last7.reduce((s, h) => s + h.price, 0) / last7.length
442	      : price;
443	  const aboveAvg7 = price > avg7;
444	
445	  // 持仓盈亏
446	  const pnl = holding ? Math.round((price - holding.avgPrice) * shares) : 0;
447	  const pnlPct = holding
448	    ? ((price - holding.avgPrice) / holding.avgPrice) * 100
449	    : 0;
450	  // PnL颜色：中国/A股标准 — 盈利红/亏损绿（涨红跌绿）
451	  const pnlColor = pnl >= 0 ? "var(--danger)" : "var(--success)";
452	  // 涨跌颜色：红涨绿跌（中国/A股标准）
453	  const trendColor = todayChange >= 0 ? "var(--danger)" : "var(--success)";
454	  const trendIcon = todayChange >= 0 ? "▲" : "▼";
455	
456	  // 全买/全卖能买多少
457	  const maxBuy = calcMaxBuyShares(stock.symbol);
458	  const maxSell = shares;
459	
460	  return `
461	    <div class="action-card stock-card" style="border-left:3px solid ${trendColor};">
462	      <div style="display:flex;justify-content:space-between;align-items:flex-start;">
463	        <div>
464	          <div class="card-title" style="margin:0;">${stock.symbol} ${stock.name}</div>
465	          <div style="font-size:10px;color:var(--text-muted);">${stock.industry} | 波动率${(stock.volatility * 100).toFixed(0)}%</div>
466	        </div>
467	        <div style="text-align:right;">
468	          <div style="font-size:18px;font-weight:700;color:${trendColor};">¥${price.toFixed(2)}</div>
469	          <div style="font-size:11px;color:${trendColor};">${trendIcon} ${todayChange >= 0 ? "+" : ""}${todayChange.toFixed(2)} (${todayPct >= 0 ? "+" : ""}${todayPct.toFixed(2)}%)</div>
470	        </div>
471	      </div>
472	
473	      <div style="display:flex;justify-content:space-between;align-items:center;margin:4px 0;font-size:10px;color:var(--text-muted);">
474	        <span>7日均 ¥${avg7.toFixed(2)} ${aboveAvg7 ? "🔴" : "🟢"}</span>
475	        <span>20日高 ¥${market.high20.toFixed(2)}</span>
476	        <span>20日低 ¥${market.low20.toFixed(2)}</span>
477	      </div>
478	
479	      ${renderKLine(market.history, price)}
480	
481	      ${
482	        shares > 0
483	          ? `
484	        <div style="margin-top:8px;padding:6px 8px;background:rgba(0,180,216,0.06);border-radius:4px;font-size:11px;">
485	          <div style="display:flex;justify-content:space-between;">
486	            <span>持仓: <strong>${shares}</strong>股 | 均价 <strong>¥${holding.avgPrice.toFixed(2)}</strong></span>
487	            <span style="color:${pnlColor};font-weight:600;">${pnl >= 0 ? "+" : ""}¥${pnl.toLocaleString()} (${pnlPct >= 0 ? "+" : ""}${pnlPct.toFixed(1)}%)</span>
488	          </div>
489	        </div>
490	      `
491	          : ""
492	      }
493	
494	      <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:8px;">
495	        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="10">买10</button>
496	        <button class="btn btn-sm btn-success stock-buy" data-sym="${stock.symbol}" data-qty="100">买100</button>
497	        <button class="btn btn-sm btn-success stock-buy-all" data-sym="${stock.symbol}" ${maxBuy === 0 ? "disabled" : ""} title="用所有现金按当前价买入">📦 全部买入 (${maxBuy})</button>
498	        <button class="btn btn-sm btn-danger stock-sell" data-sym="${stock.symbol}" data-qty="10" ${shares === 0 ? "disabled" : ""}>卖10</button>
499	        <button class="btn btn-sm btn-danger stock-sell-all" data-sym="${stock.symbol}" ${shares === 0 ? "disabled" : ""} title="卖出全部持仓">💰 全部卖出 (${shares})</button>
500	      </div>
501	    </div>
502	  `;
503	}
504	
505	function showStockTradeModal() {
506	  const state = StateManager.getState();
507	  // 首次打开：bootstrap 历史
508	  if (Object.values(state.corporate.stockMarket).some((m) => !m._initialized)) {
509	    bootstrapStockHistory(state);
510	  }
511	
512	  // 持仓概览
513	  const totalStockValue = state.corporate.stocks.reduce((sum, s) => {
514	    const m = state.corporate.stockMarket[s.symbol];
515	    return sum + (m ? m.price * s.shares : 0);
516	  }, 0);
517	  const totalCost = state.corporate.stocks.reduce(
518	    (sum, s) => sum + s.avgPrice * s.shares,
519	    0,
520	  );
521	  const totalPnL = Math.round(totalStockValue - totalCost);
522	  const pnlColor = totalPnL >= 0 ? "var(--danger)" : "var(--success)";
523	
524	  let body = `
525	    <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 12px;background:var(--bg-card);border-radius:6px;margin-bottom:12px;">
526	      <div>
527	        <div style="font-size:11px;color:var(--text-muted);">现金</div>
528	        <div style="font-size:16px;font-weight:600;color:var(--success);">¥${state.resources.cash.toLocaleString()}</div>
529	      </div>
530	      <div>
531	        <div style="font-size:11px;color:var(--text-muted);">持仓市值</div>
532	        <div style="font-size:16px;font-weight:600;">¥${totalStockValue.toLocaleString()}</div>
533	      </div>
534	      <div>
535	        <div style="font-size:11px;color:var(--text-muted);">浮动盈亏</div>
536	        <div style="font-size:16px;font-weight:600;color:${pnlColor};">${totalPnL >= 0 ? "+" : ""}¥${totalPnL.toLocaleString()}</div>
537	      </div>
538	    </div>
539	    <p style="font-size:11px;color:var(--text-muted);margin-bottom:8px;">
540	      💡 提示：每只股票有独立的行业、波动率，会受公司新闻影响。价格每日波动 + 漂移 + 回归。
541	    </p>
542	    <div style="max-height:55vh;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:8px;">
543	  `;
544	
545	  for (const stock of STOCK_LIST) {
546	    body += renderStockCard(stock, state);
547	  }
548	  body += "</div>";
549	
550	  showModal({
551	    title: "📈 股票交易 (8只多行业)",
552	    body,
553	    buttons: [
554	      {
555	        text: "🚀 刷新行情",
556	        cls: "btn-primary",
557	        callback: () => {
558	          // 模拟一次价格更新看看效果
559	          updateStockPrices(state, false);
560	          showStockTradeModal();
561	        },
562	      },
563	      {
564	        text: "关闭",
565	        cls: "",
566	        callback: () => {
567	          renderAll();
568	        },
569	      },
570	    ],
571	  });
572	
573	  // 绑定按钮
574	  setTimeout(() => {
575	    document.querySelectorAll(".stock-buy").forEach((btn) => {
576	      btn.onclick = () => {
577	        buyStock(btn.dataset.sym, parseInt(btn.dataset.qty));
578	        showStockTradeModal();
579	      };
580	    });
581	    document.querySelectorAll(".stock-buy-all").forEach((btn) => {
582	      btn.onclick = () => {
583	        const sym = btn.dataset.sym;
584	        const qty = calcMaxBuyShares(sym);
585	        if (qty > 0) {
586	          buyStock(sym, qty);
587	        } else {
588	          StateManager.addMessage("⚠️ 现金不足买入 1 股。", "warning");
589	        }
590	        showStockTradeModal();
591	      };
592	    });
593	    document.querySelectorAll(".stock-sell").forEach((btn) => {
594	      btn.onclick = () => {
595	        const sym = btn.dataset.sym;
596	        const qty = parseInt(btn.dataset.qty);
597	        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
598	        if (holding && holding.shares > 0) {
599	          sellStock(sym, Math.min(qty, holding.shares));
600	        }
601	        showStockTradeModal();
602	      };
603	    });
604	    document.querySelectorAll(".stock-sell-all").forEach((btn) => {
605	      btn.onclick = () => {
606	        const sym = btn.dataset.sym;
607	        const holding = state.corporate.stocks.find((s) => s.symbol === sym);
608	        if (holding && holding.shares > 0) {
609	          sellStock(sym, holding.shares);
610	        } else {
611	          StateManager.addMessage("⚠️ 没有持仓可卖。", "warning");
612	        }
613	        showStockTradeModal();
614	      };
615	    });
616	  }, 50);
617	}
618	
619	/** 刷新行情的辅助函数（季度切换时调用） */
620	function refreshStockMarket(state) {
621	  updateStockPrices(state, true);
622	  bootstrapStockHistory(state);
623	}
