1	/**
2	 * 房产市场周期引擎 — 让房价真正波动起来
3	 *
4	 * 设计原则：
5	 * - 房价不再固定增值，而是随市场周期、行业热度、政策、新闻波动
6	 * - 参考中国房地产市场真实周期的四个阶段拐点
7	 * - 海外房产受国内市场影响小（低 zoneWeight.sectorHeat）
8	 * - 与新闻系统、世界参数反馈环、投资系统形成完整联动
9	 *
10	 * █ 市场阶段 ███████████████████████████████████
11	 *   boom   火爆  → 活跃上涨，政策风险积累
12	 *   stable 平稳  → 正常波动，基线状态
13	 *   cooling 降温 → 价格回落，成交量萎缩
14	 *   bust   萧条  → 加速下跌，恐慌情绪
15	 * █████████████████████████████████████████████
16	 */
17	
18	// ====== 阶段定义 ======
19	const PROPERTY_PHASES = {
20	  boom: {
21	    label: "🔥 楼市火爆",
22	    icon: "📈",
23	    driftMin: 0.0008,
24	    driftMax: 0.0025,
25	    minDuration: 15,
26	    maxDuration: 45,
27	    color: "var(--danger)",
28	  },
29	  stable: {
30	    label: "➡️ 市场平稳",
31	    icon: "➡️",
32	    driftMin: -0.0005,
33	    driftMax: 0.0008,
34	    minDuration: 20,
35	    maxDuration: 60,
36	    color: "var(--text-muted)",
37	  },
38	  cooling: {
39	    label: "❄️ 市场降温",
40	    icon: "📉",
41	    driftMin: -0.0015,
42	    driftMax: -0.0003,
43	    minDuration: 15,
44	    maxDuration: 40,
45	    color: "var(--info)",
46	  },
47	  bust: {
48	    label: "💥 楼市萧条",
49	    icon: "💥",
50	    driftMin: -0.003,
51	    driftMax: -0.0008,
52	    minDuration: 10,
53	    maxDuration: 30,
54	    color: "var(--success)",
55	  },
56	};
57	
58	// ====== 阶段转换消息 ======
59	const PHASE_TRANSITION_MSGS = {
60	  boom: "🔥 楼市火爆！房价持续上涨，但政策风险在积累…",
61	  stable: "➡️ 楼市进入平稳期，价格波动收窄。",
62	  cooling: "❄️ 楼市开始降温，注意控制房产仓位。",
63	  bust: "💥 楼市萧条！房价持续下跌，抄底还是逃离？",
64	};
65	
66	// ====== 初始化 ======
67	
68	/**
69	 * 初始化房产市场系统
70	 * 新游戏 / 存档迁移时调用
71	 */
72	function initPropertyMarket(state) {
73	  var inv = state.investment;
74	  if (!inv) return;
75	
76	  // 已初始化则跳过
77	  if (inv._propertySystemV2) return;
78	
79	  // 设置初始市场阶段
80	  inv.propertyMarketPhase = "stable";
81	  inv.propertyPhaseStartDay = state.player.day;
82	  inv.propertyPhaseDuration = getRandomPhaseDuration("stable");
83	  inv._propertyPolicyTightness = 0;
84	  inv._propertySystemV2 = true;
85	
86	  // 迁移已持有房产：补充新字段
87	  var props = inv.properties || [];
88	  for (var i = 0; i < props.length; i++) {
89	    var p = props[i];
90	    var def = getPropertyDef(p.id);
91	    if (def) {
92	      p.zone = def.zone;
93	      p.zoneWeight = JSON.parse(JSON.stringify(def.zoneWeight));
94	      p.volatility = def.volatility;
95	      p.baseAppreciation = def.baseAppreciation;
96	    } else {
97	      // 兜底（理论上不会发生）
98	      p.zone = "general";
99	      p.zoneWeight = { sectorHeat: 0.8, policy: 0.8, cycle: 0.8 };
100	      p.volatility = 0.004;
101	      p.baseAppreciation = 0.0;
102	    }
103	  }
104	
105	  StateManager.addMessage(
106	    "📊 房产市场系统已升级：价格将随市场波动，不再固定增值。",
107	    "hint",
108	  );
109	}
110	
111	/** 从 PROPERTIES 常量查找房产定义（兼容未加载时的回退） */
112	function getPropertyDef(propId) {
113	  if (typeof PROPERTIES === "undefined") return null;
114	  for (var i = 0; i < PROPERTIES.length; i++) {
115	    if (PROPERTIES[i].id === propId) return PROPERTIES[i];
116	  }
117	  return null;
118	}
119	
120	// ====== 每日更新 ======
121	
122	/**
123	 * 每日房产市场更新（由 tickInvestmentDaily 调用，替换原有内联逻辑）
124	 */
125	function tickPropertyMarket(state) {
126	  var inv = state.investment;
127	  if (!inv) return;
128	
129	  // 1. 检查是否需要阶段转换
130	  checkPhaseTransition(state);
131	
132	  // 2. 政策趋紧度自然衰减（每天 2% 向 0 回归）
133	  if (inv._propertyPolicyTightness) {
134	    inv._propertyPolicyTightness *= 0.98;
135	    if (Math.abs(inv._propertyPolicyTightness) < 0.01) {
136	      inv._propertyPolicyTightness = 0;
137	    }
138	  }
139	
140	  // 3. 为每套已持有房产计算当天的价格变化
141	  var props = inv.properties || [];
142	  for (var i = 0; i < props.length; i++) {
143	    var prop = props[i];
144	    var def = getPropertyDef(prop.id);
145	
146	    var changeMult = calculatePropertyDailyChange(prop, def, state);
147	
148	    prop.currentPrice = Math.round(
149	      (prop.currentPrice || prop.buyPrice) * changeMult,
150	    );
151	    // 保底价（不低于买入价的 10%，防止归零）
152	    var floor = Math.round((prop.buyPrice || 0) * 0.1);
153	    if (prop.currentPrice < floor) prop.currentPrice = floor;
154	
155	    // 月租结算（维持原逻辑）
156	    var isSelfLived = inv.selfLivePropertyId === prop.id;
157	    if (state.player.day % 30 === 0 && !isSelfLived) {
158	      state.resources.cash += prop.rent || 0;
159	    }
160	  }
161	}
162	
163	// ====== 阶段转换逻辑 ======
164	
165	/**
166	 * 检查并执行市场阶段转换
167	 */
168	function checkPhaseTransition(state) {
169	  var inv = state.investment;
170	  var phase = inv.propertyMarketPhase || "stable";
171	  var daysInPhase = state.player.day - (inv.propertyPhaseStartDay || 0);
172	  var duration = inv.propertyPhaseDuration || 30;
173	
174	  var shouldTransition = false;
175	
176	  // 条件A：阶段持续期满
177	  if (daysInPhase >= duration) {
178	    shouldTransition = true;
179	  }
180	
181	  // 条件B：sectorHeat 阈值触发（每日检查）
182	  var heat = 1.0;
183	  if (typeof getSectorHeat === "function") {
184	    heat = getSectorHeat("房地产");
185	  }
186	
187	  if (phase !== "boom" && heat >= 1.15 && daysInPhase >= 10) {
188	    // 行业热度高→转向火爆
189	    transitionPropertyPhase(state, "boom");
190	    return;
191	  }
192	  if (phase !== "bust" && heat <= 0.8 && daysInPhase >= 10) {
193	    // 行业热度极低→转向萧条
194	    transitionPropertyPhase(state, "bust");
195	    return;
196	  }
197	  if (phase === "stable" && heat <= 0.9 && daysInPhase >= 10) {
198	    // 热度小幅低于正常→降温
199	    transitionPropertyPhase(state, "cooling");
200	    return;
201	  }
202	
203	  // 条件C：活跃新闻中的强房地产新闻
204	  var newsDriven = checkNewsDrivenTransition(state, phase);
205	  if (newsDriven) return;
206	
207	  // 条件D：随机提前结束（每日 10% 概率，需至少持续 10 天）
208	  if (!shouldTransition && daysInPhase >= 10 && Math.random() < 0.1) {
209	    shouldTransition = true;
210	  }
211	
212	  if (shouldTransition) {
213	    transitionPropertyPhase(state);
214	  }
215	}
216	
217	/**
218	 * 检查活跃新闻是否强制驱动阶段转换
219	 */
220	function checkNewsDrivenTransition(state, currentPhase) {
221	  var activeNews = state.activeNews || [];
222	  for (var i = 0; i < activeNews.length; i++) {
223	    var n = activeNews[i];
224	    // 强利空新闻：强制转向降温（除非已在萧条）
225	    if (
226	      (n.id === "property_cooling" ||
227	        n.id === "developer_default" ||
228	        n.id === "property_tax_pilot") &&
229	      currentPhase !== "bust" &&
230	      currentPhase !== "cooling"
231	    ) {
232	      transitionPropertyPhase(state, "cooling");
233	      return true;
234	    }
235	    // 强刺激新闻：强制转向火爆（除非已在火爆）
236	    if (n.id === "property_stimulus" && currentPhase !== "boom") {
237	      transitionPropertyPhase(state, "boom");
238	      return true;
239	    }
240	  }
241	  return false;
242	}
243	
244	/**
245	 * 执行阶段转换
246	 * @param {object} state - 游戏状态
247	 * @param {string} forcedPhase - 强制指定目标阶段（可选）
248	 */
249	function transitionPropertyPhase(state, forcedPhase) {
250	  var inv = state.investment;
251	  var currentPhase = inv.propertyMarketPhase || "stable";
252	
253	  var newPhase;
254	  if (forcedPhase) {
255	    newPhase = forcedPhase;
256	  } else {
257	    newPhase = pickNextPhase(state, currentPhase);
258	  }
259	
260	  if (!newPhase || newPhase === currentPhase) return;
261	
262	  // 执行转换
263	  inv.propertyMarketPhase = newPhase;
264	  inv.propertyPhaseStartDay = state.player.day;
265	  inv.propertyPhaseDuration = getRandomPhaseDuration(newPhase);
266	
267	  // 发送转换消息
268	  var msg =
269	    PHASE_TRANSITION_MSGS[newPhase] || "🏠 房产市场进入" + newPhase + "阶段。";
270	  var msgType = "info";
271	  if (newPhase === "boom") msgType = "warning";
272	  if (newPhase === "bust") msgType = "danger";
273	  StateManager.addMessage(msg, msgType);
274	}
275	
276	/**
277	 * 基于权重随机选择下一个阶段
278	 * 不允许从 boom→bust 或 bust→boom 的跳跃
279	 */
280	function pickNextPhase(state, currentPhase) {
281	  var phases = ["boom", "stable", "cooling", "bust"];
282	  var weights = { boom: 0, stable: 0, cooling: 0, bust: 0 };
283	
284	  var heat = 1.0;
285	  if (typeof getSectorHeat === "function") {
286	    heat = getSectorHeat("房地产");
287	  }
288	  var tightness = state.investment._propertyPolicyTightness || 0;
289	
290	  // 为每个潜在目标赋权重
291	  for (var i = 0; i < phases.length; i++) {
292	    var target = phases[i];
293	
294	    // 不能转到自己
295	    if (target === currentPhase) {
296	      weights[target] = 0;
297	      continue;
298	    }
299	
300	    // 禁止跳级：boom↔bust 不能直接转换
301	    if (
302	      (currentPhase === "boom" && target === "bust") ||
303	      (currentPhase === "bust" && target === "boom")
304	    ) {
305	      weights[target] = 0;
306	      continue;
307	    }
308	
309	    // 基础权重
310	    weights[target] = 20;
311	
312	    // sectorHeat 调节
313	    if (target === "boom") {
314	      if (heat > 1.1) weights[target] += 40;
315	      else if (heat < 0.9) weights[target] -= 10;
316	    }
317	    if (target === "cooling" || target === "bust") {
318	      if (heat < 0.9) weights[target] += 40;
319	      else if (heat > 1.1) weights[target] -= 10;
320	    }
321	
322	    // 政策趋紧度调节
323	    if (target === "cooling" && tightness > 0.2) weights[target] += 20;
324	    if (target === "boom" && tightness < -0.2) weights[target] += 20;
325	    if (target === "stable" && Math.abs(tightness) < 0.2) weights[target] += 15;
326	
327	    // 当前阶段的惯性（偏向相邻阶段）
328	    if (currentPhase === "boom" && target === "stable") weights[target] += 15;
329	    if (currentPhase === "bust" && target === "cooling") weights[target] += 15;
330	    if (currentPhase === "cooling" && target === "bust") weights[target] += 10;
331	    if (currentPhase === "cooling" && target === "stable")
332	      weights[target] += 10;
333	    if (currentPhase === "stable" && target === "cooling")
334	      weights[target] += 10;
335	    if (currentPhase === "stable" && target === "boom") weights[target] += 10;
336	
337	    // 保底权重为正
338	    if (weights[target] < 1) weights[target] = 1;
339	  }
340	
341	  // 加权随机选择
342	  var totalWeight = 0;
343	  for (var w in weights) totalWeight += weights[w];
344	
345	  if (totalWeight <= 0) return "stable";
346	
347	  var r = Math.random() * totalWeight;
348	  var cumulative = 0;
349	  for (var pi = 0; pi < phases.length; pi++) {
350	    var p = phases[pi];
351	    cumulative += weights[p];
352	    if (r <= cumulative) return p;
353	  }
354	
355	  return "stable";
356	}
357	
358	// ====== 价格计算 ======
359	
360	/**
361	 * 计算单套房产当天的价格变化乘数
362	 *
363	 * 变化率 = cycleDrift + sectorDrift + policyDrift + baseAppreciation + noise
364	 * 乘数 = 1 + 变化率
365	 * 最终 = 乘数 × newsMul
366	 */
367	function calculatePropertyDailyChange(prop, propDef, state) {
368	  var inv = state.investment;
369	  var phase = inv.propertyMarketPhase || "stable";
370	
371	  // 1. 周期漂移（根据市场阶段）
372	  var cycleDrift = getCycleDrift(phase);
373	
374	  // 2. 行业热度漂移（sectorHeat["房地产"] 偏离 1.0 的 5% 转化为日漂移）
375	  var sectorDrift = 0;
376	  if (typeof getSectorHeat === "function") {
377	    var heat = getSectorHeat("房地产");
378	    var zoneWeight = (propDef && propDef.zoneWeight) ||
379	      prop.zoneWeight || {
380	        sectorHeat: 0.8,
381	      };
382	    sectorDrift = (heat - 1.0) * 0.05 * (zoneWeight.sectorHeat || 0.8);
383	  }
384	
385	  // 3. 政策漂移（政策趋紧度 × 系数 × 政策敏感度）
386	  var tightness = inv._propertyPolicyTightness || 0;
387	  var policyWeight =
388	    (propDef && propDef.zoneWeight && propDef.zoneWeight.policy) ||
389	    (prop.zoneWeight && prop.zoneWeight.policy) ||
390	    0.8;
391	  var policyDrift = tightness * 0.002 * policyWeight;
392	
393	  // 4. 基础增值（房产自身的结构性趋势）
394	  var baseAppr =
395	    propDef && typeof propDef.baseAppreciation === "number"
396	      ? propDef.baseAppreciation
397	      : typeof prop.baseAppreciation === "number"
398	        ? prop.baseAppreciation
399	        : 0.0;
400	
401	  // 5. 每日噪声
402	  var vol = (propDef && propDef.volatility) || prop.volatility || 0.004;
403	  var noise = (Math.random() - 0.5) * 2 * vol;
404	
405	  // 6. 新闻乘数
406	  var newsMul = 1.0;
407	  if (typeof getNewsEffectForProperty === "function") {
408	    newsMul = getNewsEffectForProperty(state);
409	  }
410	
411	  // 总变化率
412	  var totalDrift = cycleDrift + sectorDrift + policyDrift + baseAppr + noise;
413	
414	  // 限制单日最大涨跌幅度（防止极端值）
415	  totalDrift = Math.max(-0.08, Math.min(0.08, totalDrift));
416	
417	  // 保守乘数 = (1 + 漂移)，乘以新闻乘数
418	  var mult = (1 + totalDrift) * newsMul;
419	
420	  return mult;
421	}
422	
423	/**
424	 * 根据当前市场阶段获取日周期漂移值
425	 */
426	function getCycleDrift(phase) {
427	  var def = PROPERTY_PHASES[phase];
428	  if (!def) return 0;
429	  return def.driftMin + Math.random() * (def.driftMax - def.driftMin);
430	}
