432	/**
433	 * 获取随机阶段持续期
434	 */
435	function getRandomPhaseDuration(phase) {
436	  var def = PROPERTY_PHASES[phase];
437	  if (!def) return 30;
438	  return (
439	    def.minDuration +
440	    Math.floor(Math.random() * (def.maxDuration - def.minDuration + 1))
441	  );
442	}
443	
444	// ====== UI 辅助函数 ======
445	
446	/**
