460	
461	  var tightness = inv._propertyPolicyTightness || 0;
462	  var policyLabel =
463	    tightness > 0.2
464	      ? "🏛️ 调控趋紧"
465	      : tightness < -0.2
466	        ? "🏛️ 政策宽松"
467	        : "🏛️ 政策中性";
468	
469	  var daysInPhase = state.player.day - (inv.propertyPhaseStartDay || 0);
470	
471	  return (
472	    '<div style="padding:8px 12px;margin-bottom:12px;background:rgba(255,255,255,0.03);border:1px solid ' +
473	    def.color +
474	    ';border-radius:6px;font-size:11px;display:flex;justify-content:space-between;align-items:center;">' +
475	    '<span><strong style="color:' +
476	    def.color +
